const pages = {
  about: { title: 'About Godoma TTI', eyebrow: 'Our institute', intro: 'Godoma Technical Training Institute is a public technical training institute in Vitengeni, Kilifi County, committed to equipping youth with practical, entrepreneurial and employable skills.', sections: [['Who we are', 'Godoma TTI is the first public sub-county technical training institute in Kilifi County. Since opening in 2016, the institute has provided accessible technical and vocational education and training for young people and working adults across the region.'], ['Our role in Kenya', 'The institute contributes to Kenya’s skills development agenda by preparing competent graduates for employment, self-employment, enterprise, innovation and further learning. Training combines classroom knowledge, practical workshop experience, digital literacy, industry exposure and responsible citizenship.'], ['Vision', 'To be a centre of excellence in technical training.'], ['Mission', 'To provide quality, relevant and accessible technical training for sustainable development.'], ['Core values', 'Respect, quality, excellence, integrity, discipline, equity and teamwork.'], ['Training environment', 'Godoma TTI offers a supportive learning environment with practical workshops, ICT laboratories, a library, student support services, co-curricular activities, industry engagement and dedicated teaching and non-teaching staff.'], ['Academic departments', 'The institute delivers training through Electrical and Electronics Engineering, Building and Civil Engineering, Computing and Informatics, Automotive and Mechanical Engineering, and Agricultural Studies. Programmes include Diploma, Certificate and Artisan pathways, subject to current course offerings and entry requirements.'], ['Brief history', 'Godoma Technical Training Institute was commissioned in November 2016 and is located in Vitengeni near Kilifi County. The campus sits in a serene setting bordering the famous Dida Forest, where the welcoming local community promotes peaceful coexistence. The institute continues to grow as a centre for quality learning, research, innovation and practical skills development.'], ['Partners and quality assurance', 'Godoma TTI works within Kenya’s TVET system and engages with national education, examination, placement, loans and industrial training institutions, including TVETA, KNEC, KUCCPS, HELB and NITA.']] },
  'notice-board': { title: 'Notice Board', eyebrow: 'Updates and announcements', intro: 'Find the latest admissions notices, student updates, events and official institute information in one place.', sections: [['HELB TVET Loans & Bursaries', 'HELB finances TVET students in over 200 technical institutes. Eligible trainees in approved TVET CDACC programmes can apply for tuition and upkeep support through the official HELB channels.'], ['Motivational Talk', 'The Office of the Dean of Students invites staff and trainees to a talk on coronavirus, HIV/AIDS, drugs, mental health and discipline at GTTI Phase II.'], ['Service Charter', 'Read the Godoma TTI Service Charter in English and Kiswahili for information about our services, commitments and customer care standards.']] },
  governance: { title: 'Godoma TTI Governance', eyebrow: 'Leadership and accountability', intro: 'Godoma Technical Training Institute is headed by a Board of Management (BOM), which provides strategic direction, stewardship and accountability for the institute.', sections: [['Message from the Chairperson', 'Welcome to Godoma Technical Training Institute. As Chairman of the Board of Governors, I am delighted to be part of Godoma’s journey towards achieving its vision of becoming a centre of excellence in technical training, research and business incubation. At Godoma, we are committed to providing accessible, quality, needs-based technical and vocational training that equips learners with practical, market-relevant skills to thrive in the national and global economy. Beyond preparing graduates for employment, we aim to nurture entrepreneurship, innovation and business creation, empowering our learners to create opportunities for themselves and others while contributing to sustainable livelihoods and economic development. As a Board, we are actively fulfilling our strategic oversight role to support the Institute in achieving its mission. We are committed to strengthening institutional governance, promoting sustainable growth, and ensuring that Godoma continues to improve the quality and relevance of its training while creating greater opportunities for our learners. Achieving this vision requires the collective effort of all stakeholders. We therefore welcome collaboration, ideas and constructive contributions from our students, staff, parents, industry partners, government agencies, development partners, alumni and the wider community. Our doors remain open to engagement and input from all those who share our aspirations for Godoma. I invite you all to join hands with the Board and Management in building a stronger, more responsive and sustainable institution — one that develops skilled, competent and innovative graduates who can contribute meaningfully to society and the economy.\n\nEmmanuel Kadenge Masha\nChairman, Board of Governors\nGodoma Technical Training Institute']] },
  administration: { title: 'Administration', eyebrow: 'Supporting student success', intro: 'Meet the offices responsible for leadership, academic delivery, trainee welfare and institute operations.', sections: [['Principal’s office', 'Provides institutional leadership, planning and quality assurance.'], ['Deputy Principal — Administration', 'Coordinates administration, operations, staff support and institutional services.'], ['Deputy Principal — Academics', 'Coordinates academic planning, training delivery, examinations and departmental performance.'], ['Registrar', 'Guides applicants through admission, registration, academic records and certification.'], ['Dean of Students', 'Supports trainee welfare, guidance, discipline and co-curricular life.'], ['Finance Office', 'Manages fees, financial records, budgeting and responsible stewardship of institute resources.'], ['Procurement Office', 'Coordinates transparent acquisition of goods and services in support of training and operations.']] },
  'deputy-principal-administration': { title: 'Deputy Principal — Administration', eyebrow: 'Administration', intro: 'The Deputy Principal’s Office coordinates academic and operational activities that keep training programmes running effectively.', sections: [] },
  'deputy-principal-academics': { title: 'Deputy Principal — Academics / Training', eyebrow: 'Administration', intro: 'Supporting relevant, practical and high-quality technical education for every trainee.', sections: [] },
  finance: { title: 'Finance Office', eyebrow: 'Administration', intro: 'The Finance Office supports transparent financial management, fee administration, budgeting, financial records and responsible stewardship of institute resources.', sections: [] },
  procurement: { title: 'Procurement Office', eyebrow: 'Administration', intro: 'The Procurement Office supports transparent, fair and accountable purchasing for Godoma Technical Training Institute.', sections: [] },
  'council-bog-chairperson': { title: 'Council / BOG Chairperson', eyebrow: 'Administration', intro: 'The Council and Board of Governors Chairperson provides strategic oversight and supports accountable leadership at Godoma Technical Training Institute.', sections: [['Strategic oversight', 'The Chairperson guides the Council and Board in setting priorities that strengthen teaching, training, governance and institutional development.'], ['Accountability', 'The office works with institute leadership to promote transparency, responsible stewardship and effective implementation of approved plans.']] },
  'principal-office': { title: 'Principal Office', eyebrow: 'Administration', intro: 'The Principal’s Office provides executive leadership for the institute and coordinates the delivery of quality technical training.', sections: [] },
  'deputy-principal-office': { title: 'Deputy Principal Office', eyebrow: 'Administration', intro: 'The Deputy Principal’s Office coordinates academic and operational activities that keep training programmes running effectively.', sections: [['Academic coordination', 'The office supports the planning and monitoring of teaching, examinations, timetables and departmental performance.'], ['Operations', 'The Deputy Principal works with staff and institute leadership to maintain efficient day-to-day academic operations.']] },
  'dean-of-students': { title: 'Dean of Students', eyebrow: 'Administration', intro: 'The Dean of Students supports trainee welfare, discipline, guidance and a positive campus experience.', sections: [] },
  'recognition-of-prior-learning': { title: 'Recognition of Prior Learning (RPL)', eyebrow: 'Administration', intro: 'Recognition of Prior Learning provides a pathway for experienced individuals to have skills and knowledge gained through work, life experience, informal learning, or previous training assessed and recognised.', sections: [['What is RPL?', 'RPL is an assessment process that identifies, documents, and evaluates a candidate’s existing competencies against the requirements of a recognised course or qualification. It focuses on what a candidate can demonstrate, not only where or how the learning was acquired.'], ['Who can apply?', 'RPL may support applicants and workers who have gained relevant skills through employment, enterprise, community service, apprenticeships, informal training, or other practical experience. Candidates should provide evidence of their experience and be ready to demonstrate their competence through the assessment process.'], ['The process', 'Applicants receive guidance on the relevant qualification, submit evidence, participate in counselling and assessment, and receive feedback on the outcome. Where gaps are identified, the institute may recommend targeted training before reassessment.'], ['Why RPL matters', 'RPL promotes access, mobility, lifelong learning, and fair recognition of practical skills while helping employers and industries access a more capable workforce. Contact the institute for current application requirements and assessment guidance.']] },
  'industrial-liaison-office': { title: 'Industrial Liaison Office', eyebrow: 'Administration', intro: 'It is my pleasure to serve as the Industry Liaison Officer at Godoma Technical Training Institute, fostering strong partnerships between the Institute and industry to promote skills development, dual training implementation, and employment opportunities for our students.', sections: [['Industry collaboration', 'At Godoma TTI, we are committed to aligning training with industry needs. Through collaboration with employers and industry stakeholders, we create opportunities for industrial attachment, internships, workplace experience, and career development, preparing our learners for the demands of the modern workplace.'], ['A message to our students and partners', 'I encourage our students to embrace these opportunities, build professional networks, and develop the practical skills needed to succeed in today’s competitive job market. I also invite industry partners to collaborate with Godoma TTI in nurturing talent and building a skilled, competent, and productive workforce.'], ['Join Godoma TTI', 'Your future career starts with the right skills! Enrol at Godoma TTI today and gain the practical training, industry exposure, and professional competencies you need to succeed. Choose Godoma TTI, build your skills, and turn your ambitions into reality.']] },
  'registrar-office': { title: 'Registrar Office', eyebrow: 'Administration', intro: '', sections: [['Admissions and registration', 'The office guides applicants through entry requirements, course selection, admission and registration procedures.'], ['Academic records', 'The Registrar maintains accurate trainee records and supports official communication on examinations, progression and certification.']] },
  iqa: { title: 'IQA (Internal Quality Assurance Office)', eyebrow: 'Administration', intro: 'The objective of Technical and Vocational Education and Training (TVET) is to equip trainees with relevant skills and competencies for the world of work. At Godoma Technical Training Institute, quality assurance is central to the delivery of effective, relevant, and competency-based training.', sections: [['Quality assurance at Godoma TTI', 'The Internal Quality Assurance (IQA) Office coordinates quality assurance activities to ensure compliance with established training standards, institutional policies, and regulatory requirements. The office monitors training delivery and assessment, conducts internal quality audits, identifies areas for improvement, and promotes continuous enhancement of institutional processes and trainee learning outcomes.'], ['A culture of quality', 'Through collaboration with management, trainers, and other stakeholders, the office strives to foster a culture of quality, accountability, and excellence in training and service delivery.']] },
  'assessment-office': { title: 'Assessment Office', eyebrow: 'Administration', intro: 'The Assessment Office supports fair, reliable, and well-coordinated assessment processes that help trainees demonstrate the knowledge, skills, and competencies developed through their training.', sections: [] },
  admissions: { title: 'Admissions', eyebrow: 'Start your technical journey', intro: 'Applications are open for TVET CDACC programmes at Levels 3, 4, 5 and 6 across our five departments.', sections: [['Entry requirements', 'TVET CDACC programme entry requirements vary by level and course. Confirm the specific requirements for Levels 3, 4, 5 and 6 with the Admissions Office.'], ['accommodation', 'Contact the institute for current information about accommodation and student support.']] },
  funding: { title: 'Student Funding in Kenya', eyebrow: 'Financial support for training', intro: 'Information to help Godoma TTI trainees explore available funding options for technical and vocational education and training in Kenya.', sections: [['HELB TVET loans', 'Eligible Kenyan trainees in approved TVET programmes may apply for Higher Education Loans Board (HELB) TVET support. Depending on eligibility and the current funding cycle, support may contribute towards tuition and upkeep. Apply through the official HELB channels and provide accurate admission and identification details.'], ['TVET scholarships and bursaries', 'Students may also explore scholarships and bursaries offered through the Higher Education Financing portal, county governments, constituency offices, the National Government Constituencies Development Fund (NG-CDF), foundations, and other recognised sponsors. Availability, requirements, and deadlines vary by provider.'], ['How to prepare', 'Keep your admission letter, national identification details, KCSE or equivalent results, family and financial information, passport photos, and any documents requested by the funding provider ready. Apply early and retain copies or confirmation messages for your records.'], ['Important guidance', 'Funding is subject to the rules, assessment, and budgets of the relevant provider. Godoma TTI does not guarantee approval. Confirm current requirements and application deadlines directly through official government or funding-provider channels, and avoid paying unauthorised agents for funding applications.']] },
  trainees: { title: 'Trainee services', eyebrow: 'Everything you need on campus', intro: 'Find the digital services, downloads and student activities that support your training experience.', sections: [['portal', 'Access student services, notices and academic information through the student portal.'], ['elearning', 'Continue learning beyond the classroom with digital course resources and guided study.'], ['downloads', 'Find admission letters, forms and student notices from the registry.'], ['aids-control', 'The Aids Control Unit provides information, prevention education and confidential support.'], ['events', 'Keep up with institute events, student activities and important dates.']] },
  'guidance-counselling': { title: 'Guidance and Counselling', eyebrow: 'Trainee support', intro: 'The Guidance and Counselling Office supports trainees through their academic journey, personal growth, and overall well-being in a caring and supportive environment.', sections: [['A supportive office', 'It is my pleasure to serve and support our students as the Head of Guidance and Counselling. I am committed to helping you navigate your academic journey, personal growth, and overall well-being in a caring and supportive environment.'], ['Always open to listen', 'My office is always open to listen, guide, and encourage you. Stay positive no matter the situation you are in and share the challenges with your friends as much as possible. Remember, seeking support is a sign of strength, and together we can overcome any challenge.'], ['Your well-being matters', 'Your well-being matters, your dreams are valid, and your success is our joy.']] },
  library: { title: 'Library', eyebrow: 'Learn beyond the classroom', intro: 'The Godoma TTI library supports research, assignments and independent learning for every department.', sections: [['Library services', 'Access reference materials, course texts and a quiet environment for study.'], ['Opening hours', 'Visit the library notice board or contact the institute for the current timetable.']] },
  downloads: { title: 'Downloads', eyebrow: 'Resources and forms', intro: 'Access useful institute resources, forms and notices for applicants, trainees and members of the Godoma TTI community.', sections: [['Admission resources', 'Download application guidance, entry requirement information and registration checklists before beginning your technical training journey.'], ['Trainee resources', 'Find student forms, service information and academic support resources to help you manage your training experience.'], ['Official notices', 'Keep up with official institute circulars, event notices and important updates published by the administration.'], ['Need help?', 'If you cannot find the resource you need, contact the Registrar Office or use the Contact Us page for assistance.']] },
  contact: { title: 'Contact Godoma TTI', eyebrow: 'We are here to help', intro: 'Reach the institute for admissions guidance, course information, partnerships and general enquiries.', sections: [['Phone', '+254 743 661 423'], ['Email', 'godomatti.gtti@gmail.com'], ['Address', 'Matanomane, Vitengeni Rd, Kilifi County, Kenya']] },
} as const

const boardMembers = [
  { name: 'Emmanuel Masha', role: 'Chairman of the Board', photo: '/images/board/image1.webp', bio: 'Emmanuel Masha Kadenge holds a bachelor’s degree in Agriculture from the University of Nairobi and is pursuing a master’s degree in Project Management. He has over 16 years of cumulative work experience, including service with the Ministry of Agriculture and an NGO in Turkana. He currently works as a social worker at Samaritan Pass, empowering farmers through goat farming, and is also an agripreneur involved in cashew nut farming and processing.' },
  { name: 'Caroline Musyimi', role: 'Principal / Board Secretary', photo: '/images/principal-portrait-updated.webp', bio: 'Ms Caroline has served as Deputy Principal of Godoma Technical Training Institute since February 2025. She holds a master’s degree in Educational Technology and previously served as an Assessment Officer and Research Officer at TVET CDACC. She also served as Head of Department for Mechanical Engineering at Coast Institute of Technology. To date, she has 11 years of work experience.' },
  { name: "Patrick King’oina", role: 'Member', photo: '/images/board/image2.webp', bio: 'Patrick King’oina is an Electrical Trainer by profession and holds a master’s degree in Business Management. He served at Machakos TTI, rising from trainer to Head of Department and Registrar, before serving as Deputy Principal and Principal at Coast Institute of Technology. He later served as Principal at Ahamed Shahame TTI. He has also served as KATTI National Treasurer and on the KUCCPS Board of Directors, and was among the pioneers of the solar curriculum.' },
  { name: 'Moses Kesis', role: 'Member', photo: null, bio: 'Moses Kesis holds a degree in Tourism Management and is pursuing a master’s degree in Tourism Management. He has over 10 years of experience working in the tourism sector.' },
  { name: 'Esther Njoki Gacheru', role: 'Member', photo: '/images/board/esther-njoki-gacheru.webp', bio: 'Esther Njoki Gacheru is based in Murang’a County and has worked at the Technical University of Mombasa since 2010. She holds a Bachelor of Technology Education and a master’s degree in Construction Project Management, and is pursuing a PhD. She is a trained TVET trainer through TVET CDACC and GIZ, and is a registered assessor and verifier.' },
  { name: 'Caroline Chilango', role: 'Member', photo: null, bio: 'Caroline Chilango is an advocate who serves as a director in charge of budget and economic matters at the Office of the Deputy President. She has previously worked with the IEBC, served as a legal adviser to the former Governor of Kilifi County, and lectures part-time at Pwani University. She also runs a law firm in Kilifi and supports education initiatives and school development projects. She serves as Chairperson of the Law Society Maritime Committee and advocates for TVET maritime programmes.' },
  { name: 'Juliet Mapenzi Rua', role: 'Member', photo: null, bio: 'Juliet Mapenzi Rua is a community development professional and a resident of Kilifi County. She has worked with NGOs and PricewaterhouseCoopers as a Monitoring and Evaluation Officer, and served as an Assistant Chief for six years. She currently works as Assistant Director in the Governor’s Delivery Unit at the County Government of Kilifi and is passionate about education, especially girl-child education.' },
  { name: 'Mwalawari Sheti', role: 'Member', photo: '/images/board/mwalawari-sheti.webp', bio: 'Mwalawari Sheti is a Mathematics and Chemistry teacher by profession. He has served as a part-time lecturer at Pwani University, worked with the IIEC and Mbegu Fund, and currently serves as Secretary to the Municipal Board in Kwale County.' },
  { name: 'Edith Kwekwe Marafa', role: 'Member', photo: '/images/board/edith-kwekwe-marafa.webp', bio: 'Edith Kwekwe Marafa joined the board on 9 July 2025. She holds a PhD in Business Administration (Strategic Management) from JKUAT, a master’s degree in Business Administration from JKUAT, and a Bachelor of Business Administration degree from Kenya Methodist University, Marketing Option. To date, she has 12 years of work experience.' },
]

export function generateStaticParams() { return Object.keys(pages).map((slug) => ({ slug })) }

export default async function InformationPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params
  const page = pages[slug as keyof typeof pages]
  if (!page) notFound()
  const isGovernance = slug === 'governance'
  const isAbout = slug === 'about'
  const isDownloads = slug === 'downloads'
  const isPrincipalOffice = slug === 'principal-office'
  const isDeputyPrincipalOffice = slug === 'deputy-principal-office'
  const isDeanOfStudents = slug === 'dean-of-students'
  const isIqa = slug === 'iqa'
  const isIlo = slug === 'industrial-liaison-office'
  const isRplOffice = slug === 'recognition-of-prior-learning'
  const isRegistrarOffice = slug === 'registrar-office'
  const isAssessmentOffice = slug === 'assessment-office'
  const isGuidanceCounselling = slug === 'guidance-counselling'
  const principalMessage = [
    'We strive to create a supportive, inclusive, and learner-centred environment where every trainee is encouraged to discover their potential, develop their abilities, and pursue their ambitions. Through the dedication of our trainers and staff, we endeavour to maintain high standards of professionalism, discipline, integrity, and excellence in all our training programmes and institutional activities.',
    'As the world continues to embrace technological advancement and innovation, Godoma TTI remains committed to adapting to emerging trends and industry demands. We recognize the importance of digital literacy, creativity, critical thinking, and problem-solving in preparing our trainees for the modern workplace. By strengthening partnerships with industry, government agencies, development partners, and other stakeholders, we seek to enhance training opportunities and bridge the gap between classroom learning and practical workplace experience.',
    'We also believe that education goes beyond acquiring technical skills. It involves developing responsible citizens who demonstrate ethical values, teamwork, leadership, environmental awareness, and a commitment to community development. Our goal is to produce competent graduates who can contribute positively to society and participate meaningfully in Kenya’s economic transformation.',
    'I extend a warm invitation to prospective trainees, parents and guardians, industry partners, and all stakeholders to join us in our journey towards excellence. Your continued support, collaboration, and confidence in our institution are essential to achieving our shared goals and expanding opportunities for our trainees.',
    'As you explore our website, I encourage you to learn more about our programmes, admission opportunities, institutional activities, and commitment to skills development. We look forward to welcoming you to our institution and supporting you as you take the next step towards achieving your career aspirations.',
    'Thank you for choosing Godoma Technical Training Institute. Together, let us build a future founded on skills, innovation, integrity, and opportunity.',
    'Welcome to Godoma TTI — where skills are nurtured, talents are transformed, and futures are built.',
  ]
  return <><TopBar /><SiteHeader /><main key={slug}><section className="border-b border-primary/10 bg-primary py-20 text-primary-foreground sm:py-24"><div className="mx-auto max-w-7xl px-4 lg:px-8"><p className="text-xs font-bold uppercase tracking-[0.24em] text-accent">{page.eyebrow}</p><h1 className="mt-4 max-w-4xl text-balance text-4xl font-extrabold tracking-tight sm:text-5xl lg:text-6xl">{page.title}</h1><p className="mt-5 max-w-3xl text-pretty text-lg leading-relaxed text-primary-foreground/80">{page.intro}</p></div></section>{slug === 'trainees' && <section id="downloads" className="border-b bg-card py-12"><div className="mx-auto max-w-5xl px-4"><div className="mb-6"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Student resources</p><h2 className="mt-2 text-3xl font-extrabold text-primary">Trainee downloads</h2><p className="mt-2 max-w-2xl leading-relaxed text-muted-foreground">Download the forms, guides and official resources you need during your training journey.</p></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{[
  ['Admission joining instructions', '/downloads/admission-joining-instructions.pdf'],
  ['Application form', '/downloads/application-form.pdf'],
  ['Student personal details form', '/downloads/student-personal-details-form.pdf'],
  ['Course acceptance form', '/downloads/course-acceptance-form.pdf'],
  ['Rules and regulation declaration form', '/downloads/rules-regulation-declaration-form.pdf'],
  ['Hostel rules and regulation declaration form', '/downloads/hostel-rules-regulation-declaration-form.pdf'],
  ['Deferment form', '/downloads/deferment-form.pdf'],
  ['Attachment assessment form', '/downloads/attachment-assessment-form.pdf'],
  ['Attachment logbook', '/downloads/attachment-logbook.pdf'],
  ['Godoma TTI brochure', '/downloads/godoma-tti-brochure.pdf'],
  ['KUCCPS students fee structure', '/downloads/fee-structure.pdf'],
].map(([label, href]) => <a key={href} href={href} download className="rounded-lg border border-border bg-background p-5 transition-colors hover:border-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><p className="text-lg font-bold text-primary">{label}</p><span className="mt-4 inline-flex text-sm font-semibold text-accent">Download PDF</span></a>)}</div></div></section>} {isRegistrarOffice && <section className="border-b bg-card py-12"><div className="mx-auto max-w-5xl px-4"><article className="grid gap-8 md:grid-cols-[280px_1fr] md:items-start"><div className="relative aspect-[4/5] overflow-hidden border border-border shadow-xl"><Image src="/images/registrar-office-thumbnail.jpeg" alt="Registrar Office" fill className="object-cover" sizes="(min-width: 768px) 280px, 100vw" /></div><div></div></article></div></section>} {(slug === 'finance' || slug === 'procurement') && <section className="border-b bg-card py-12"><div className="mx-auto max-w-5xl px-4"><article className="grid gap-8 md:grid-cols-[280px_1fr] md:items-start"><div className="relative aspect-[4/5] overflow-hidden border border-border shadow-xl"><Image src={slug === 'finance' ? 'https://hebbkx1anhila5yf.public.blob.vercel-storage.com/finance%20office-qVGjpDSIjDvULpYJZpRCaKXwrzURqi.jpeg' : '/images/procurement-officer.jpeg'} alt={slug === 'finance' ? 'CPA Joseph Muema David, Finance Office' : 'Abdulhaq Abdulaziz, Procurement Office'} fill className="object-cover" sizes="(min-width: 768px) 280px, 100vw" /></div><div><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">{slug === 'finance' ? 'Finance Office' : 'Procurement Office'}</p><h2 className="mt-2 text-3xl font-extrabold text-primary">{slug === 'finance' ? 'CPA Joseph Muema David' : 'Abdulhaq Abdulaziz'}</h2><p className="mt-5 leading-relaxed text-muted-foreground">{slug === 'finance' ? 'Welcome to Godoma TTI! It is my pleasure to support you as the Finance Officer of Godoma TTI. I am committed to ensuring that financial services are delivered efficiently, transparently, and in a student-friendly manner to support your academic journey. My office is always open to assist you with fee-related matters and provide guidance whenever needed. Together, let us work towards a smooth and successful learning experience. Your investment in education is a step towards a brighter future, and we are here to support you every step of the way. Finance Officer, Godoma Technical Training Institute.' : "At Godoma Technical Training Institute, every workshop tool, classroom resource, and piece of equipment you use is the result of careful planning and responsible purchasing. The Procurement Office exists to make sure that our trainees and staff have the right materials, at the right time, at the best possible value. We are committed to transparency, fairness, and accountability in every purchase we make. By following proper procedures and working with trusted suppliers, we protect the Institute's resources and ensure that quality training is never compromised. To our colleagues, we ask for early and clear requisitions so that we can serve you better. To our trainees, we encourage you to take good care of the equipment and resources provided, as they are shared assets meant to benefit many generations of learners. Thank you for your continued trust and cooperation. Together, we are building a stronger Godoma Technical Training Institute."}</p></div></article></div></section>} {(slug === 'deputy-principal-administration' || slug === 'deputy-principal-academics') && <section className="border-b bg-card py-12"><div className="mx-auto max-w-5xl px-4"><article className="grid gap-8 md:grid-cols-[280px_1fr] md:items-start"><div className="relative aspect-[4/5] overflow-hidden border border-border shadow-xl"><Image src={slug === 'deputy-principal-administration' ? '/images/deputy-principal-administration.webp' : '/images/deputy-principal-academics.webp'} alt={slug === 'deputy-principal-administration' ? 'Festus Mugogo, Deputy Principal Administration' : 'Franco Mwadzo Mwangala, Deputy Principal Academics and Training'} fill className="object-cover" sizes="(min-width: 768px) 280px, 100vw" /></div><div><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">{slug === 'deputy-principal-administration' ? 'Deputy Principal — Administration' : 'Deputy Principal — Academics / Training'}</p><h2 className="mt-2 text-3xl font-extrabold text-primary">{slug === 'deputy-principal-administration' ? 'Festus Mugogo' : 'Franco Mwadzo Mwangala'}</h2><div className="mt-5 space-y-4 leading-relaxed text-muted-foreground">{slug === 'deputy-principal-administration' ? <><p>Welcome to the Deputy Principal Administration's Office. We are committed to strengthening the systems and services that support effective teaching, learning, staff coordination, trainee welfare, discipline, and the smooth day-to-day operation of Godoma Technical Training Institute. Through teamwork, accountability, and responsive leadership, we work to create a safe, orderly, inclusive, and supportive environment where every member of the GTTI community can thrive.</p><p>Our office values professionalism, integrity, communication, and continuous improvement. We welcome collaboration with staff, trainees, parents, industry partners, and other stakeholders as we build an institution that delivers quality training and serves the community with excellence.</p></> : <><p>The Academics and Training Office is dedicated to ensuring that every trainee receives relevant, practical, and high-quality technical education. We coordinate curriculum delivery, timetables, assessment, examinations, trainer support, departmental performance, and continuous improvement across our programmes.</p><p>Our focus is to connect classroom learning with workshop practice and the changing needs of industry. By promoting discipline, innovation, critical thinking, digital skills, and competency-based training, we prepare graduates for employment, entrepreneurship, further learning, and meaningful contribution to Kenya’s development.</p></>}</div></div></article></div></section>} {isGovernance && <section className="border-b bg-card py-12 shadow-md shadow-primary/5"><div className="mx-auto grid max-w-5xl items-stretch gap-8 px-4 md:grid-cols-[minmax(220px,0.7fr)_minmax(0,1.3fr)]"><div className="relative min-h-[360px] overflow-hidden rounded-lg shadow-md md:min-h-[460px]"><Image src="/images/board/image1.webp" alt="Emmanuel Masha, Chairman of the Board" fill className="object-cover object-center" sizes="(min-width: 768px) 35vw, 100vw" priority /></div><div className="flex flex-col justify-center py-2"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Message from the Chairperson</p><h2 className="mt-2 text-3xl font-extrabold text-primary">Emmanuel Masha</h2><p className="mt-1 text-sm font-semibold text-muted-foreground">Chairman, Board of Governors</p><div className="mt-6 leading-relaxed text-muted-foreground"><p className="whitespace-pre-line">{(page.sections?.[0]?.[1] ?? '').split('Emmanuel Kadenge Masha')[0].trim()}</p><div className="mt-6 border-t border-border pt-5"><p className="text-lg font-bold text-primary">Emmanuel Kadenge Masha</p><p className="mt-1 text-sm font-semibold text-accent">Chairman, Board of Governors</p><p className="mt-1 text-sm text-muted-foreground">Godoma Technical Training Institute</p></div></div></div></div></section>}{slug === 'notice-board' && <section className="bg-background py-12"><div className="mx-auto max-w-5xl px-4"><div className="grid gap-6 md:grid-cols-2">{news.map((item) => <article key={item.title} id={item.href.split('#')[1]} className="overflow-hidden rounded-xl border border-border bg-card shadow-sm"><div className="relative aspect-[16/9] overflow-hidden bg-muted"><Image src={item.image} alt={item.title} fill className="object-cover" sizes="(min-width: 768px) 50vw, 100vw" /></div><div className="p-6"><p className="text-sm font-semibold uppercase tracking-wide text-accent">{item.date}</p><h2 className="mt-2 text-2xl font-bold text-card-foreground">{item.title}</h2><p className="mt-3 leading-relaxed text-muted-foreground">{item.excerpt}</p></div></article>)}</div></div></section>}{isRplOffice && <section className="border-b bg-card py-12 shadow-md shadow-primary/5"><div className="mx-auto grid max-w-5xl items-stretch gap-8 px-4 md:grid-cols-[minmax(320px,0.9fr)_minmax(0,1.1fr)]"><div className="relative min-h-[420px] overflow-hidden rounded-lg shadow-md md:min-h-[520px]"><Image src="/images/rpl-officer-loise-loloju.webp" alt="Loise Loloju, Recognition of Prior Learning Officer" fill className="object-cover object-center" sizes="(min-width: 768px) 45vw, 100vw" priority /></div><div className="flex flex-col justify-center py-2"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Recognition of Prior Learning Office</p><h2 className="mt-2 text-3xl font-extrabold text-primary">Loise Loloju</h2><p className="mt-1 font-semibold text-muted-foreground">Recognition of Prior Learning Officer</p><div className="mt-6 space-y-4 text-muted-foreground"><p className="leading-relaxed">It is my pleasure to lead the Recognition of Prior Learning (RPL) programme at Godoma Technical Training Institute, where we recognize and certify skills and knowledge gained through work experience, informal training, and practical activities.</p><p className="leading-relaxed">At Godoma TTI, we believe that your skills deserve recognition, and your experience can open doors to new opportunities. Through RPL, skilled individuals can have their competencies assessed and certified, enhancing their career prospects and opening pathways to further education and training.</p><p className="leading-relaxed">I invite artisans, entrepreneurs, experienced workers, and all individuals with practical skills but no formal certification to enrol in our RPL programme. Do not let a lack of certification limit your potential. Take the bold step towards gaining formal recognition for the skills you already possess.</p><p className="font-semibold leading-relaxed text-primary">ENROL FOR RPL AT GODOMA TTI TODAY! Turn your skills into qualifications, your experience into opportunity, and your ambition into success. Your journey towards professional recognition starts here!</p></div></div></div></section>}{isRegistrarOffice && <section className="border-b bg-card py-12 shadow-md shadow-primary/5"><div className="mx-auto grid max-w-5xl items-stretch gap-8 px-4 md:grid-cols-[minmax(320px,0.9fr)_minmax(0,1.1fr)]"><div className="relative min-h-[420px] overflow-hidden rounded-lg shadow-md md:min-h-[520px]"><Image src="/images/registrar-office-thumbnail.webp" alt="Eric Mutai, Registrar, working in the Registrar Office" fill className="object-cover object-center" sizes="(min-width: 768px) 45vw, 100vw" priority /></div><div className="flex flex-col justify-center py-2"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Message from the Registrar</p><h2 className="mt-2 text-3xl font-extrabold text-primary">Eric Mutai</h2><p className="mt-1 font-semibold text-muted-foreground">Registrar</p><div className="mt-6 space-y-4 text-muted-foreground"><p className="leading-relaxed">Welcome to our institution, where excellence meets opportunity. As the Registrar, I am delighted to invite you to be part of a vibrant learning community committed to academic excellence, innovation, and personal growth.</p><p className="leading-relaxed">We take pride in providing quality education, supportive learning environments, and the skills needed to succeed in today’s competitive world. Whether you are beginning your academic journey or advancing your career, our institution offers the opportunity to unlock your potential and shape a brighter future.</p><p className="font-semibold leading-relaxed text-primary">Choose excellence. Choose opportunity. Choose us. We look forward to welcoming you and being part of your success story.</p></div></div></div></section>}<section className="py-16"><div className="mx-auto max-w-5xl px-4">{isAssessmentOffice && <article className="mb-12 overflow-hidden rounded-lg border bg-card shadow-sm"><div className="grid gap-0 md:grid-cols-[280px_1fr]"><div className="relative aspect-[4/5] bg-muted md:aspect-auto md:min-h-[360px]"><Image src="/images/assessment-officer.webp" alt="Assessment Officer working at a desk" fill className="object-cover object-center" sizes="(min-width: 768px) 280px, 100vw" /></div><div className="flex flex-col justify-center p-6 sm:p-8"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Assessment Office</p><h2 className="mt-2 text-3xl font-extrabold text-primary">Assessment Officer</h2><p className="mt-4 leading-relaxed text-muted-foreground">The Assessment Officer coordinates fair, reliable, and well-documented assessment processes that support trainee achievement and competency-based training.</p><div className="mt-6 border-t pt-6"><h3 className="text-2xl font-bold text-primary">Assessment coordination and trainee achievement</h3><p className="mt-3 leading-relaxed text-muted-foreground">The office coordinates assessment activities across departments, supports the preparation and administration of assessments, and promotes consistency, integrity, and proper documentation throughout the assessment process. Through collaboration with trainers, departments, and institutional leadership, the Assessment Office helps ensure that trainees receive clear guidance, timely feedback, and assessment processes that reflect competency-based training standards.</p></div></div></div></article>}{isGovernance && <div className="mb-12"><div className="mb-8"><h2 className="text-3xl font-extrabold text-primary">Council / Board of Governors</h2><p className="mt-3 max-w-3xl leading-relaxed text-muted-foreground">Meet the members appointed to provide strategic direction, stewardship and accountability for Godoma Technical Training Institute.</p></div><div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">{boardMembers.map((member) => <article key={member.name} className="overflow-hidden rounded-lg border bg-card shadow-sm"><div className="relative flex h-64 items-end justify-center bg-muted">{member.photo ? <Image src={member.photo} alt={`${member.name}, ${member.role}`} fill className="object-contain object-bottom" sizes="(min-width: 1024px) 300px, (min-width: 640px) 50vw, 100vw" /> : <span className="mb-8 flex size-28 items-center justify-center rounded-full bg-primary text-4xl font-extrabold text-primary-foreground">{member.name.split(' ').map((part) => part[0]).slice(0, 2).join('')}</span>}</div><div className="p-5"><h3 className="text-xl font-bold text-primary">{member.name}</h3><p className="mt-1 text-sm font-semibold uppercase tracking-wide text-accent">{member.role}</p><p className="mt-4 text-sm leading-relaxed text-muted-foreground">{member.bio}</p></div></article>)}</div></div>}{isGuidanceCounselling && <div className="mb-12 overflow-hidden rounded-lg border bg-card shadow-lg shadow-primary/10"><div className="grid items-stretch lg:grid-cols-[220px_1fr]"><div className="relative min-h-72 bg-muted"><Image src="/images/guidance-counselling-hod.webp" alt="Magego Hussein, Head of Guidance and Counselling" fill className="object-cover" sizes="(min-width: 1024px) 220px, 100vw" priority /></div><div className="flex flex-col justify-center p-6 sm:p-8"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Trainee Support</p><h2 className="mt-3 text-3xl font-extrabold text-primary">Magego Hussein</h2><p className="mt-1 font-semibold text-muted-foreground">Head of Guidance and Counselling</p><p className="mt-4 leading-relaxed text-muted-foreground">Supporting trainees through their academic journey, personal growth, and overall well-being.</p></div></div></div>}{isIlo && <div className="mb-12 overflow-hidden rounded-lg border bg-card shadow-lg shadow-primary/10"><div className="grid items-stretch lg:grid-cols-[220px_1fr]"><div className="relative min-h-72 bg-muted"><Image src="/images/ilo-officer.webp" alt="Abdulrehman Ahmed Khator, Industry Liaison Officer at Godoma Technical Training Institute" fill className="object-cover" sizes="(min-width: 1024px) 220px, 100vw" priority /></div><div className="flex flex-col justify-center p-6 sm:p-8"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Industry Liaison Office</p><h2 className="mt-3 text-3xl font-extrabold text-primary">Abdulrehman Ahmed Khator</h2><p className="mt-1 font-semibold text-muted-foreground">Industry Liaison Officer</p><p className="mt-4 leading-relaxed text-muted-foreground">Connecting trainees with industry, workplace exposure, and employment pathways.</p></div></div></div>}{isIqa && <div className="mb-12 overflow-hidden rounded-lg border bg-card shadow-lg shadow-primary/10"><div className="grid items-stretch lg:grid-cols-[220px_1fr]"><div className="relative min-h-72 bg-muted"><Image src="/images/iqa-officer.webp" alt="IQA officer at Godoma Technical Training Institute" fill className="object-cover" sizes="(min-width: 1024px) 220px, 100vw" priority /></div><div className="flex flex-col justify-center p-6 sm:p-8"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Internal Quality Assurance Office</p><h2 className="mt-3 text-3xl font-extrabold text-primary">IQA Officer</h2><p className="mt-4 leading-relaxed text-muted-foreground">Supporting quality, accountability, and excellence in training and service delivery.</p></div></div></div>}{isAbout && <div className="mb-12 overflow-hidden rounded-lg border bg-card shadow-lg shadow-primary/10"><div className="grid items-stretch lg:grid-cols-[1.1fr_0.9fr]"><div className="relative min-h-80 bg-muted"><Image src="/images/about-campus.jpg" alt="Godoma Technical Training Institute campus building and grounds" fill className="object-cover" sizes="(min-width: 1024px) 55vw, 100vw" priority /></div><div className="flex flex-col justify-center p-6 sm:p-8"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">A place to learn and grow</p><h2 className="mt-3 text-3xl font-extrabold text-primary">Skills, character and opportunity</h2><p className="mt-4 leading-relaxed text-muted-foreground">From practical workshops to supportive student services, Godoma TTI helps learners build the confidence and competence needed for Kenya’s changing world of work.</p></div></div></div>}<div className="grid gap-6 lg:grid-cols-2">{(isGovernance ? page.sections.slice(1) : page.sections).map(([heading, text]) => <article id={heading.toLowerCase().replaceAll(' ', '-')} key={heading} className="rounded-lg border bg-card p-6 shadow-md shadow-primary/5 transition-shadow hover:shadow-lg hover:shadow-primary/10"><h2 className="flex items-center gap-3 text-xl font-extrabold text-primary"><span className="flex size-9 shrink-0 items-center justify-center rounded-md bg-accent/15 text-accent" aria-hidden="true">{heading === 'Who we are' && <Building2 className="size-5" />}{heading === 'Our role in Kenya' && <Target className="size-5" />}{heading === 'Vision' && <Compass className="size-5" />}{heading === 'Mission' && <Lightbulb className="size-5" />}{heading === 'Core values' && <HeartHandshake className="size-5" />}{heading === 'Training environment' && <GraduationCap className="size-5" />}{heading === 'Academic departments' && <BriefcaseBusiness className="size-5" />}{heading === 'Brief history' && <History className="size-5" />}{heading === 'Partners and quality assurance' && <Users className="size-5" />}{!['Who we are', 'Our role in Kenya', 'Vision', 'Mission', 'Core values', 'Training environment', 'Academic departments', 'Brief history', 'Partners and quality assurance'].includes(heading) && <WalletCards className="size-5" />}</span>{heading}</h2><p className="mt-3 leading-relaxed text-muted-foreground">{text}</p></article>)}</div>{isDeanOfStudents && <section className="mt-12 overflow-hidden rounded-lg border bg-card shadow-sm"><div className="grid gap-0 lg:grid-cols-[minmax(0,0.8fr)_minmax(0,1.6fr)]"><div className="relative min-h-80 bg-muted"><img src="/images/dean-of-students.jpeg" alt="Lemmy Gunga, Dean of Students" className="h-full min-h-80 w-full object-cover" /></div><div className="p-6 sm:p-8"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Message from the Dean of Students</p><h2 className="mt-2 text-2xl font-extrabold text-primary">Lemmy Gunga</h2><p className="mt-1 text-sm font-semibold uppercase tracking-wide text-muted-foreground">Dean of Students</p><p className="mt-6 text-pretty leading-relaxed text-muted-foreground">Welcome to the Office of the Dean of Students. Our commitment is to support every trainee’s welfare, personal growth, and success throughout their time at Godoma Technical Training Institute. We provide a welcoming and inclusive environment where students can access guidance, mentorship, counselling, and support as they pursue their academic and career goals.</p><p className="mt-4 text-pretty leading-relaxed text-muted-foreground">We encourage all trainees to uphold discipline, respect, integrity, and responsibility while taking an active role in student leadership, clubs, co-curricular activities, and community life. Together, we can build a safe and positive campus culture that promotes wellbeing, belonging, excellence, and the development of confident and responsible citizens.</p></div></div></section>}{isDeputyPrincipalOffice && <section className="mt-12 space-y-6"><article className="overflow-hidden rounded-lg border bg-card shadow-sm"><div className="grid gap-0 lg:grid-cols-[minmax(0,0.8fr)_minmax(0,1.6fr)]"><div className="relative min-h-80 bg-muted"><img src="/images/deputy-principal-administration.webp" alt="Festus Mugogo, Deputy Principal Administration" className="h-full min-h-80 w-full object-cover" /></div><div className="p-6 sm:p-8"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Deputy Principal — Administration</p><h2 className="mt-2 text-2xl font-extrabold text-primary">Festus Mugogo</h2><p className="mt-6 text-pretty leading-relaxed text-muted-foreground">Welcome to the Deputy Principal Administration’s Office. We are committed to strengthening the systems and services that support effective teaching, learning, staff coordination, trainee welfare, discipline, and the smooth day-to-day operation of Godoma Technical Training Institute. Through teamwork, accountability, and responsive leadership, we work to create a safe, orderly, inclusive, and supportive environment where every member of the GTTI community can thrive.</p><p className="mt-4 text-pretty leading-relaxed text-muted-foreground">Our office values professionalism, integrity, communication, and continuous improvement. We welcome collaboration with staff, trainees, parents, industry partners, and other stakeholders as we build an institution that delivers quality training and serves the community with excellence.</p></div></div></article><article className="overflow-hidden rounded-lg border bg-card shadow-sm"><div className="grid gap-0 lg:grid-cols-[minmax(0,0.8fr)_minmax(0,1.6fr)]"><div className="relative min-h-80 bg-muted"><img src="/images/deputy-principal-academics.webp" alt="Franco Mwadzo Mwangala, Deputy Principal Academics and Training" className="h-full min-h-80 w-full object-cover" /></div><div className="p-6 sm:p-8"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Deputy Principal — Academics / Training</p><h2 className="mt-2 text-2xl font-extrabold text-primary">Franco Mwadzo Mwangala</h2><p className="mt-6 text-pretty leading-relaxed text-muted-foreground">The Academics and Training Office is dedicated to ensuring that every trainee receives relevant, practical, and high-quality technical education. We coordinate curriculum delivery, timetables, assessment, examinations, trainer support, departmental performance, and continuous improvement across our programmes.</p><p className="mt-4 text-pretty leading-relaxed text-muted-foreground">Our focus is to connect classroom learning with workshop practice and the changing needs of industry. By promoting discipline, innovation, critical thinking, digital skills, and competency-based training, we prepare graduates for employment, entrepreneurship, further learning, and meaningful contribution to Kenya's development.</p></div></div></article></section>}{isPrincipalOffice && <section className="mt-12 overflow-hidden rounded-lg border bg-card shadow-sm"><div className="grid gap-0 lg:grid-cols-[minmax(0,0.8fr)_minmax(0,1.6fr)]"><div className="relative min-h-80 bg-muted"><Image src="/images/principal-portrait-updated.webp" alt="Caroline Musyimi, Principal of Godoma Technical Training Institute" fill className="object-cover" sizes="(max-width: 1024px) 100vw, 40vw" /></div><div className="p-6 sm:p-8"><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Message from the Principal</p><h2 className="mt-2 text-3xl font-extrabold text-primary">Caroline Musyimi</h2><p className="mt-1 text-sm font-semibold uppercase tracking-wide text-muted-foreground">Principal, Godoma Technical Training Institute (GTTI)</p><div className="mt-6 space-y-4 text-pretty leading-relaxed text-muted-foreground">{principalMessage.map((paragraph) => <p key={paragraph}>{paragraph}</p>)}</div><p className="mt-6 font-semibold text-primary">Caroline Musyimi<br />Principal<br />Godoma Technical Training Institute</p></div></div></section>}{isDownloads && <section className="mt-12 rounded-lg border bg-card p-6 shadow-sm"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold uppercase tracking-[0.2em] text-accent">Official publication</p><h2 className="mt-2 text-2xl font-extrabold text-primary">Godoma TTI Brochure</h2><p className="mt-2 leading-relaxed text-muted-foreground">Download the institute brochure for courses, admissions, facilities and contact information.</p></div><a href="/downloads/godoma-tti-brochure.pdf" download className="inline-flex shrink-0 items-center justify-center rounded-md bg-primary px-5 py-3 font-bold text-primary-foreground transition hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2">Download brochure</a></div></section>}{slug === 'contact' && <div className="mt-12"><ContactForm /></div>}<div className="mt-10"><Link href="/" className="font-bold text-primary hover:text-accent">Back to home</Link></div></div></section></main><SiteFooter /></>
}
